#include <cstddef>

template <std::size_t N>
struct Ring {
    int data_[N]{};
    std::size_t head_ = 0;
    // TODO: push writes at head_ % N then advances; capacity() returns N.
    void push(int v);
    int at(std::size_t i) const { return data_[i % N]; }
    static constexpr std::size_t capacity();
};

